D[1864]={"^Reduces the cooldown of your Demonic Empowerment, Metamorphosis, Inferno, Ritual of Doom, and Fel Domination spells by (.-)%%, and the cooldown of your Demonic Leap by (.-) seconds%.\n\n|cFFAAAAAACapstone Bonus: While in Metamorphosis your Hand of Gul'dan can be cast twice within (.-) before going on cooldown%.|r%s*$","Reduz em {{1}}% a recarga de Empoderamento Demoníaco, Metamorfose, Inferno, Ritual da Perdição e Dominação Vil, e reduz em {{2}} s a recarga de Salto Demoníaco.\n\n|cFFAAAAAABônus de Ápice: enquanto estiver em Metamorfose, Mão de Gul'dan pode ser lançada duas vezes dentro de {{3}} antes de entrar em recarga.|r"}
D[1865]={"^Reduces the cooldown of your Demonic Empowerment, Metamorphosis, Inferno, Ritual of Doom, and Fel Domination spells by (.-)%%, and the cooldown of your Demonic Leap by (.-) seconds%.\n\nCapstone Bonus: While in Metamorphosis your Hand of Gul'dan can be cast twice within (.-) before going on cooldown%.%s*$","Reduz em {{1}}% a recarga de Empoderamento Demoníaco, Metamorfose, Inferno, Ritual da Perdição e Dominação Vil, e reduz em {{2}} s a recarga de Salto Demoníaco.\n\nBônus de Ápice: enquanto estiver em Metamorfose, Mão de Gul'dan pode ser lançada duas vezes dentro de {{3}} antes de entrar em recarga."}
D[2617]={"^|cFF66DDFFLevel 10 Passive|r\nDoubles the base Weapon Damage dealt by |cffffffffInfernal Strike|r and increases all critical damage dealt by (.-)%%%.%s*$","|cFF66DDFFPassivo de Nível 10|r\nDuplica o dano base de arma causado por |cffffffffGolpe Infernal|r e aumenta todo o dano crítico causado em {{1}}%."}
