D[63771]={"^Curse an enemy for (.-), causing (.-) Shadow Damage every (.-) for (.-)%. \n\nIf you use |cffffffffDemonflare|r within (.-), you curse your target with |cffffffffRitual Fire|r for (.-)%.\n\nCasting |cffffffffCurse of Hel'nurath|r on a target afflicted with |cffffffffRitual Fire|r will apply |cffffffffBlack Shield|r to you%.s:805679:0@:ext@%s*$","Amaldiçoa um inimigo durante {{1}}, causando {{2}} de dano de Sombra cada {{3}} durante {{4}}.\n\nSe lança |cffffffffClarão Demoníaco|r dentro de {{5}}, amaldiçoa o alvo com |cffffffffFogo Ritual|r durante {{6}}.\n\nLançar |cffffffffMaldição de Hel'nurath|r sobre um alvo afetado por |cffffffffFogo Ritual|r aplicará a você |cffffffffEscudo Negro|r"}
D[63795]={"^Annihilate up to (.-) enemies in a frontal cone, dealing (.-)%% Weapon Damage plus (.-) as Shadowflame Damage and generating 4 |cffff9933Demonfire|r%.\n\nDeals (.-)%% increased damage if you are above 75%% health or below 35%% health%. Scales with modifiers to |cffffffffInfernal Strike|r%.%s*$","Aniquila até {{1}} inimigos em um cone frontal, causando {{2}}% do dano da arma mais {{3}} de dano de Chama Sombria e gerando 4 |cffff9933Fogo Demoníaco|r.\n\nCausa {{4}}% a mais de dano se sua vida estiver acima de 75% ou abaixo de 35% da vida máxima. Escala com modificadores de |cffffffffGolpe Infernal|r."}
D[63836]={"^|cffff9933Generates 1 Demonfire|r\nBludgeon an enemy and all nearby enemies, dealing (.-)%% Weapon Damage%.\n\nUnleashes your active |cffffffffPestilence|r to trigger a powerful effect%.\n\nScales with modifiers to |cffffffffSever|r%.%s*$","|cffff9933Gera 1 Fogo Demoníaco|r\nGolpeia um inimigo e todos os inimigos próximos, causando {{1}}% de dano da arma.\n\nLiberar seu |cffffffffPestilência|r ativa para desencadear um poderoso efeito.\n\nEscala com modificadores a |cffffffffDecepar|r."}
D[63934]={"^|cff93cceaConsumes Deathfire Stacks|r\nStrike an enemy, dealing (.-) Fire Damage and increasing your movement speed by (.-)%% for (.-)%.\n\nIgnores immunities and resistances and increases damage the target takes from your |cFFFFFFFFDemonflare|r by (.-)%% for (.-) sec%.\n\nDeals (.-)%% increased damage per |cFFFFFFFFDeathfire|r consumed%s*$","|cff93cceaConsome Acúmulos de Fogo da Morte|r\nGolpeia um inimigo, causando {{1}} de dano de Fogo e aumentando sua velocidade de movimento em {{2}}% durante {{3}}.\n\nIgnora imunidades e resistências e aumenta em {{4}}% o dano que o alvo recebe de |cFFFFFFFFClarão Demoníaco|r durante {{5}} s.\n\nCausa {{6}}% a mais de dano por |cFFFFFFFFFogo da Morte|r consumido."}
D[63935]={"^|cff93cceaConsumes Deathfire Stacks|r\nStrike an enemy, dealing (.-) Fire Damage and increasing your movement speed by (.-)%% for (.-)%.\n\nIgnores immunities and resistances%.\n\nDeals (.-)%% increased damage per |cFFFFFFFFDeathfire|r consumed%s*$","|cff93cceaConsome Acúmulos de Fogo da Morte|r\nGolpeia um inimigo, causando {{1}} de dano de Fogo e aumentando sua velocidade de movimento em {{2}}% durante {{3}}.\n\nIgnora imunidades e resistências.\n\nCausa {{4}}% a mais de dano por |cFFFFFFFFFogo da Morte|r consumido."}
