D[64759]={"^Swing a chain at an enemy dealing (.-) Physical Damage and silencing them for (.-), generating 2 |cffff9933Demonfire|r%.\n\nIf you successfully interrupt an enemy, this will refund (.-) Rage and (.-)%% of the cooldown%.%s*$","Golpeia um inimigo com uma corrente, causando {{1}} de dano Físico e silenciando-o por {{2}}, além de gerar 2 |cffff9933Fogo Demoníaco|r.\n\nSe você interromper um inimigo com sucesso, recupera {{3}} de Raiva e {{4}}% da recarga."}
D[64799]={"^Deals Weapon Damage plus (.-) Physical Damage to an enemy, increasing based on their missing health%.\n\nGenerates 2 stacks of |cffff9933Demonfire|r%.%s*$","Causa dano da arma mais {{1}} de dano Físico um inimigo. O dano aumenta conforme a vida que falta ao alvo.\n\nGera 2 aplicações de |cffff9933Fogo Demoníaco|r."}
D[65212]={"^Bind an enemy Demon up to level (.-), forcing it to do your bidding for (.-) %(8 sec vs players%)%.\n\nWhile active, (.-)%% of all damage it takes is redirected to you%.%s*$","Vincula um demônio inimigo até nível {{1}}, obrigando-o a fazer sua vontade durante {{2}} (8 s contra jogadores).\n\nEnquanto estiver ativo, {{3}}% de todo o dano que recebe é redirecionado para você."}
D[65237]={"^|cFF66DDFFLevel 20 Passive|r\nEach |cffffffffHellfire Imp|r now reduces your Physical damage taken by (.-)%%%.%s*$","|cFF66DDFFPassivo de Nível 20|r\nCada |cffffffffDiabrete do Fogo Infernal|r agora reduz o dano Físico que recebem {{1}}%."}
D[65241]={"^|cffffffffConsumes Deathfire|r\nIncreases block chance by (.-)%% and block value by (.-)%% for (.-)%.\n\nSuccessful blocks while active trigger a |cffffffffHellish Rebuke|r%.\n\nEffectiveness increased by (.-)%% per |cffffffffDeathfire|r consumed%.%s*$","|cffffffffConsome Deathfire|r\nAumenta a chance de {{1}}% bloqueio e o valor do bloqueio em {{2}}% durante {{3}}.\n\nOs blocos bem-sucedidos Enquanto estiver ativo desencadeiam um |cffffffffRepreensão Infernal|r.\n\nA eficácia aumenta em {{4}}% para cada |cffffffffDeathfire|r consumido."}
D[65242]={"^|cffffffffConsumes Deathfire|r\nIncreases block chance by (.-)%% and block value by (.-)%% for (.-)%.\n\nEffectiveness increased by (.-)%% per |cffffffffDeathfire|r consumed%.%s*$","|cffffffffConsome Deathfire|r\nAumenta a chance de {{1}}% bloqueio e o valor do bloqueio em {{2}}% durante {{3}}.\n\nA eficácia aumenta em {{4}}% para cada |cffffffffDeathfire|r consumido."}
D[65343]={"^Deals |cffff8100(.-)%% Weapon Damage|r to an enemy target, and |cffb0f67aHeals|r you for |cfffeff9e(.-)%%|r of your Maximum |cfffeff9eHealth|r every |cfffeff9e(.-)|r sec for |cfffeff9e(.-)|r%.\n\nConsumes 1 stack of |cfffeff9eDemonfire|r%.\n\nReduces the cooldown of Flames of Xoroth by (.-) sec when used%.%s*$","Causa |cffff8100{{1}}% de dano da arma|r um alvo inimigo e te |cffb0f67aCura|r por |cfffeff9e{{2}}%|r do Máximo |cfffeff9eVida|r a cada |cfffeff9e{{3}}|r s durante |cfffeff9e{{4}}|r.\n\nGasta 1 acúmulo de |cfffeff9eFogo Demoníaco|r.\n\nReduz a recarga de chamas de Xoroth em {{5}} s ao ser usado."}
D[65474]={"^Deals (.-) Shadow Damage to an enemy and increases the initial damage they take from your next |cffffffffDemonflare|r by (.-)%%%.%s*$","causa {{1}} de dano de Sombra a um inimigo e aumenta o dano inicial que recebem do seguinte |cffffffffClarão Demoníaco|r seu em {{2}}%."}
D[65475]={"^|cff93cceaConsumes Deathfire Stacks|r\nStrike an enemy, dealing (.-) Shadowflame Damage and increasing your movement speed by (.-)%% for (.-)%.\n\nIgnores immunities and resistances and increases damage the target takes from your |cFFFFFFFFDemonflare|r by (.-)%% for (.-) sec%.\n\nDeals (.-)%% increased damage per |cFFFFFFFFDeathfire|r consumed%s*$","|cff93cceaConsome Deathfire Acúmulos|r\nGolpeia um inimigo, causando {{1}} de dano de Chama Sombria e aumenta sua velocidade de movimento em {{2}}% durante {{3}}.\n\nIgnorando imunidades e resistências e aumenta o dano que recebe o alvo por seu |cFFFFFFFFClarão Demoníaco|r em {{4}}% durante {{5}} s.\n\nCausa um aumento de {{6}}% no dano para cada |cFFFFFFFFDeathfire|r consumido."}
D[65476]={"^|cff93cceaConsumes Deathfire Stacks|r\nStrike an enemy, dealing (.-) Shadowflame Damage and increasing your movement speed by (.-)%% for (.-)%.\n\nIgnores immunities and resistances%.\n\nDeals (.-)%% increased damage per |cFFFFFFFFDeathfire|r consumed%s*$","|cff93cceaConsome Deathfire Acúmulos|r\nGolpeia um inimigo, causando {{1}} de dano de Chama Sombria e aumenta sua velocidade de movimento em {{2}}% durante {{3}}.\n\nIgnorando imunidades e resistências.\n\nCausa um aumento de {{4}}% no dano para cada |cFFFFFFFFDeathfire|r consumido."}
D[65481]={"^Embrace your inner demon, instantly generating 6 stacks of |cffff9933Demonfire|r and (.-) Rage%.%s*$","Abraça seu lado demoníaco, gerando instantaneamente 6 acúmulos de |cffff9933Fogo Demoníaco|r e {{1}} Fúria."}
D[65484]={"^Your |cffffffffCalamity|r spell is now Instant%.%s*$","Seu feitiço |cffffffffDesastre|r agora é Instantâneo."}
D[65488]={"^Dealing damage to an enemy above 75%% health now increases your critical strike chance by (.-)%% for (.-)%.%s*$","Causar dano a um inimigo acima de 75% de vida aumenta sua chance de acerto crítico em {{1}}% por {{2}}."}
D[65489]={"^Grants |cffffffffSeeking Flame|r a (.-)%% chance to generate 1 additional |cffff9933Demonfire|r when it deals damage%.\n\nChance to trigger is increased by (.-)%% for each |cffff9933Demonfire|r you have active%.%s*$","Concede a |cffffffffChama Buscadora|r {{1}}% de chance de gerar 1 |cffff9933Fogo Demoníaco|r adicional ao causar dano.\n\nA chance de ativação aumenta em {{2}}% para cada |cffff9933Fogo Demoníaco|r que você tiver ativo."}
D[65490]={"^When you spend at least 4 |cffff9933Demonfire|r stacks you now refresh the duration of your |cFFFFFFFFUnleash Apocalypse|r on the target%.%s*$","Quando gastes ao menos 4 |cffff9933Fogo Demoníaco|r, agora renova a duração de seu |cFFFFFFFFDesencadear Apocalipse|r no alvo."}
D[65491]={"^Deals |cffff8100(.-)%% Weapon Damage|r to the target%.\n\nThis ability also deals additional |cff01cdfeFire Damage|r based on your Strength to all nearby enemies affected by Flames of Xoroth%.\n\nEvery 3rd use within (.-) will call down a Molten Hellrain, dealing Fire damage to enemies in the area for a short time%.%s*$","Causa |cffff8100{{1}}% de dano da arma|r ao alvo.\n\nEsta habilidade também causa |cff01cdfeDano de Fogo|r adicional, baseado na sua Força, a todos os inimigos próximos afetados por Chamas de Xoroth.\n\nA cada terceiro uso dentro de {{2}}, invoca uma Chuva de Fogo do Inferno, causando dano de Fogo aos inimigos na área por um curto período."}
D[65946]={"^Cause an infernal trail, striking all enemies in front of you dealing weapon damage%. Burning them causing an additional 125 damage every 1 second for 30 seconds%.%s*$","Causa uma pista infernal, golpeando todos os inimigos à sua frente e causando-lhes dano da arma. Queima a seus inimigos causando-lhes um dano adicional de 125 cada 1 segundos durante 30 segundos."}
D[66743]={"^Reduces the cooldown of your Demonic Empowerment, Metamorphosis, Inferno, Ritual of Doom, and Fel Domination spells by 5%%%.%s*$","Reduz a recarga de seus feitiços Empoderamento Demoníaco, Metamorfose, Inferno, Ritual do Destino e Dominação Vil em 5%."}
D[69025]={"^Teaches you: Fel Domination%s*$","Ensina: Dominação Vil."}
D[69058]={"^Begins tethering an elemental to be your companion%. Your armor is reduced by (.-)%% while you focus on dominating the elemental for 20 sec%. If you lose the elemental's attention for any reason, the domination process will fail%. Each type of elemental has unique abilities that you will be able to make use of%.%s*$","Começa a vincular um elemental para torná-lo seu companheiro. Sua Armadura é reduzida em {{1}}% enquanto você se concentra em dominá-lo por 20 s. Se perder a atenção do elemental por qualquer motivo, o processo de dominação falhará. Cada tipo de elemental possui habilidades únicas que você poderá usar."}
D[69178]={"^Pulls the enemy to you, inflicting (.-) Physical damage%.%s*$","Arraste o inimigo até você, causando {{1}} de dano Físico."}
D[69448]={"^Attacks nearby enemies in a whirlwind of steel that lasts (.-), inflicting (.-)%% Weapon damage to enemies within 5 yards every (.-) second%.%s*$","Atinge os inimigos próximos durante {{1}} com um redemoinho de aço que causa {{2}}% de dano da arma criaturas inimigas dentro de 5 metros a cada {{3}} segundo."}
D[69504]={"^Whips the target for (.-)%% Weapon damage and increases its damage taken by (.-)%% for (.-)%. Stacking up to 100 times%.%s*$","Açoita o alvo em {{1}}% dano da arma e aumenta seu dano recebido em {{2}}% durante {{3}}. Acumula até 100 vezes."}
D[70543]={"^Begins dominating an mechanical to be your companion%. Your armor is reduced by (.-)%% while you focus on dominating the mechanical for 20 sec%. If you lose the mechanical's attention for any reason, the domination process will fail%. Once dominated, the mechanical will be very unhappy and disloyal%. Try feeding the mechanical minion immediately to make it happy%.%s*$","Começa a dominar um Mecânico para torná-lo seu companheiro. Sua Armadura é reduzida em {{1}}% enquanto você se concentra em dominá-lo por 20 s. Se perder a atenção do Mecânico por qualquer motivo, o processo de dominação falhará. Depois de dominado, ele ficará muito descontente e desleal. Alimente-o imediatamente para deixá-lo feliz."}
D[70544]={"^Begins dominating an mechanical to be your companion%. Your armor is reduced by (.-)%% while you focus on dominating the mechanical for 20 sec%. If you lose the mechanical's attention for any reason, the domination process will fail%. Each type of mechanical has unique abilities that you will be able to make use of%.%s*$","Começa a dominar um Mecânico para torná-lo seu companheiro. Sua Armadura é reduzida em {{1}}% enquanto você se concentra em dominá-lo por 20 s. Se perder a atenção do Mecânico por qualquer motivo, o processo falhará. Cada tipo de Mecânico possui habilidades únicas que você poderá usar."}
D[70545]={"^Begins dominating an giant to be your companion%. Your armor is reduced by (.-)%% while you focus on dominating the giant for 20 sec%. If you lose the giant's attention for any reason, the domination process will fail%. Once dominated, the giant will be very unhappy and disloyal%. Try feeding the giant minion immediately to make it happy%.%s*$","Começa a dominar um gigante para torná-lo seu companheiro. Sua Armadura é reduzida em {{1}}% enquanto você se concentra em dominá-lo por 20 s. Se perder a atenção do gigante por qualquer motivo, o processo de dominação falhará. Depois de dominado, ele ficará muito descontente desleal. Alimente-o imediatamente para deixá-lo feliz."}
D[70546]={"^Begins dominating an giant to be your companion%. Your armor is reduced by (.-)%% while you focus on dominating the giant for 20 sec%. If you lose the giant's attention for any reason, the domination process will fail%. Each type of giant has unique abilities that you will be able to make use of%.%s*$","Começa a dominar um gigante para torná-lo seu companheiro. Sua Armadura é reduzida em {{1}}% enquanto você se concentra em dominá-lo por 20 s. Se perder a atenção do gigante por qualquer motivo, o processo de dominação falhará. Cada tipo de gigante possui habilidades únicas que você poderá usar."}
D[70547]={"^Begins dominating an aberration to be your companion%. Your armor is reduced by (.-)%% while you focus on dominating the aberration for 20 sec%. If you lose the aberration's attention for any reason, the domination process will fail%. Once dominated, the aberration will be very unhappy and disloyal%. Try feeding the aberration minion immediately to make it happy%.%s*$","Começa a dominar uma aberração para torná-la sua companheira. Sua Armadura é reduzida em {{1}}% enquanto você se concentra em dominá-la por 20 s. Se perder a atenção da aberração por qualquer motivo, o processo de dominação falhará. Depois de dominada, ela ficará muito descontente desleal. Alimente-a imediatamente para deixá-la feliz."}
D[70548]={"^Begins dominating an aberration to be your companion%. Your armor is reduced by (.-)%% while you focus on dominating the aberration for 20 sec%. If you lose the aberration's attention for any reason, the domination process will fail%. Each type of aberration has unique abilities that you will be able to make use of%.%s*$","Começa a dominar uma aberração para torná-la sua companheira. Sua Armadura é reduzida em {{1}}% enquanto você se concentra em dominá-la por 20 s. Se perder a atenção da aberração por qualquer motivo, o processo de dominação falhará. Cada tipo de aberração possui habilidades únicas que você poderá usar."}
D[73533]={"^Increases the damage of your Demon Pet by (.-)%% and Wild Imps by 15%% and causes them to regenerate (.-) mana and (.-) health every (.-) seconds for (.-)%.%s*$","Aumenta em {{1}}% o dano do seu mascote demoníaco e em 15% o dano dos Diabretes Selvagens, além de fazer com que regenerem {{2}} de mana e {{3}} de vida a cada {{4}} s durante {{5}}."}
D[75199]={"^Increases damage done by (.-)%%%.%s*$","Aumenta o dano causado em {{1}}%."}
D[76543]={"^Increases the critical strike chance of all party and raid members by (.-)%%%. Does not stack with similar effects%.\n\nIn addition, Physical critical strikes now increase the target's Physical Damage atken by 4%% for 8 sec%.%s*$","Aumenta a chance de acerto crítico de todos membros do grupo e o enxame em {{1}}%. Não acumula com efeitos semelhantes.\n\nAlém disso, os acertos críticos físicos aumentam agora o dano Físico recebido pelo alvo em 4% durante 8 s."}
D[76635]={"^Ignite your weapon, causing you to send out searing fire with each melee critical strike, dealing (.-) Fire damage in a line and increasing your Armor penetration by (.-)%% while active%. Lasts for (.-) attacks%.\n\nLasts for 1 additional attack per |cffff9933Demonfire|r consumed%.%s*$","Acende sua arma, fazendo com quenvie fogo abrasador com cada acerto crítico de corpo a corpo, causando {{1}} de dano de Fogo em linha e aumenta seu Penetração de armadura em {{2}}% enquanto estiver ativo. Dura para {{3}} ataques.\n\nDura 1 ataque adicional por |cffff9933Fogo Demoníaco|r consumido."}
D[77225]={"^You are a demon from Xoroth, and this is your mortal visage%. Some of your abilities now generate |cffffffffDeathfire|r, which can be consumed by other abilities to unleash powerful effects on the denizens of Azeroth!\n\nYour |cffffffffDemonstrike|r now generates 1 |cffffffffDeathfire|r which can be consumed by |cffffffffFlames of Xoroth|r%. Try it!%s*$","É um demônio de Xoroth, esta é sua forma mortal. Algumas de suas habilidades agora geram |cffffffffFogo da morte|r, que pode ser consumido por outras habilidades para desatar efeitos poderosos sobre os habitamtes de Azeroth!\n\nSeu |cffffffffGolpe Demoníaco|r agora gera 1 |cffffffffFogo da morte|r que pode ser consumido por |cffffffffChamas de Xoroth|r. Experimente!"}
D[77459]={"^Your |cffffffffXorothian Warsteed|r is now instant cast and prevents roots and slows for 2 sec when cast, but now has a (.-) sec cooldown%.%s*$","Seu |cffffffffMontaria de guerra xorotiana|r agora é lançado instantaneamente impedefeitos denraizamento e lentidão durante 2 s ao ser usado, mas passa a ter {{1}} s de recarga."}
D[77462]={"^Critical strikes with |cffffffffGore|r and |cffffffffInfernal Strike|r now generate 1 additional |cffff9933Demonfire|r%.%s*$","Os acertos críticos com |cffffffffCornada|r e |cffffffffGolpe Infernal|r agora geram 1 adicional de |cffff9933Fogo Demoníaco|r."}
D[77678]={"^Your |cFFFFFFFFShieldgore|r now summons a |cffffffffHellfire Imp|r to aid you in combat for (.-), but its Rage cost is increased by (.-)%.\n\nIn addition, the maximum health of your imps is increased by (.-)%%%.%s*$","Seu |cFFFFFFFFEscudo Sangrento|r agora evoca um |cffffffffDiabrete do Fogo Infernal|r para ajudar você em combate por {{1}}, mas o custo de Raiva aumenta em {{2}}.\n\nAlém disso, a vida máxima dos seus diabretes aumenta em {{3}}%."}
D[77679]={"^Your |cffffffffInfernal Strike|r now summons a |cffffffffHellfire Imp|r to aid you in combat for (.-), but its Rage cost is increased by (.-)%.\n\nIn addition, the maximum health of your imps is increased by (.-)%%%.%s*$","Seu |cffffffffGolpe Infernal|r agora evoca um |cffffffffDiabrete do Fogo Infernal|r para ajudar você em combate por {{1}}, mas o custo de Raiva aumenta em {{2}}.\n\nAlém disso, a vida máxima dos seus diabretes aumenta em {{3}}%."}
D[78826]={"^|cFFFF33FFRequires 2 Void Runes|rYou tear open a rift into Xoroth, opening an Imp Gate that will periodically spawn imp minions to cast Fireballs upon your foes%. Lasts 18 seconds%.%s*$","|cFFFF33FFRequer 2 Runas Vazias|rTearias uma brechaté Xoroth, abrindo uma Porta de Diabrete que gerará lacaios imp periodicamente para lançar Balas de Fogo sobre seus inimigos. Dura 18 segundos."}
D[78999]={"^Your |cFFFFFFFFBlade of Xoroth|r used with 6 stacks of |cffff9933Demonfire|r now reduces the cooldown of |cFFFFFFFFDoom|r by (.-) seconds%.\n\nIn addition, while |cFFFFFFFFDoom|r is active, your |cFFFFFFFFDoomguard|r will now copy your |cFFFFFFFFBlade of Xoroth|r, dealing 50%% of the damage dealt%.%s*$","Seu |cFFFFFFFFLâmina de Xoroth|r usada com 6 acúmulos de |cffff9933Fogo Demoníaco|r agora reduz a recarga de |cFFFFFFFFFatalidade|r em {{1}} segundos.\n\nAlém disso, enquanto |cFFFFFFFFFatalidade|r estiver ativo, seu |cFFFFFFFFGuarda perdido|r copiará seu |cFFFFFFFFLâmina de Xoroth|r, causando 50% do dano que você cause."}
D[79002]={"^|cFFFFFFFFInfernal Strike|r now grants you a stack of |cFFFFFFFFXorothian Fury|r, increasing the chance for your next |cFFFFFFFFSkulltaker|r within (.-) to critically strike by (.-)%% per stack, up to 3 stacks%.\n\nAdditionally, using |cFFFFFFFFSkulltaker|r with 6 stacks of |cffff9933Demonfire|r grants you |cFFFFFFFFXorothian Rage|r, causing your next |cFFFFFFFFInfernal Strike|r within (.-) to be guaranteed to critically strike%.%s*$","|cFFFFFFFFGolpe Infernal|r agora concedem a você um acúmulo de |cFFFFFFFFFúria Xorothiana|r, aumenta a chance de que seu próximo |cFFFFFFFFCarniceiro do Crânio|r dentro de {{1}} golpeie criticamente {{2}}% por acúmulo, até 3 acúmulos.\n\nAlém disso, usar |cFFFFFFFFCarniceiro do Crânio|r com 6 acúmulos de |cffff9933Fogo Demoníaco|r concede a você |cFFFFFFFFRaiva Xorothiana|r, garantindo que seu próximo |cFFFFFFFFGolpe Infernal|r dentro de {{3}} golpeie criticamente."}
D[79003]={"^|cFFFFFFFFInfernal Strike|r now grants you a stack of |cFFFFFFFFXorothian Fury|r, increasing the chance for your next |cFFFFFFFFBlade of Xoroth|r within (.-) to critically strike by (.-)%% per stack, up to (.-) stacks%.\n\nAdditionally, using |cFFFFFFFFBlade of Xoroth|r with 6 stacks of |cffff9933Demonfire|r grants you |cFFFFFFFFXorothian Rage|r, causing your next |cFFFFFFFFInfernal Strike|r within (.-) to be guaranteed to critically strike%.%s*$","|cFFFFFFFFGolpe Infernal|r agora concedem a você um acúmulo de |cFFFFFFFFFúria Xorothiana|r, aumenta a chance de que seu próximo |cFFFFFFFFLâmina de Xoroth|r dentro de {{1}} golpeie criticamente {{2}}% por acúmulo, até {{3}} acúmulos.\n\nAlém disso, usar |cFFFFFFFFLâmina de Xoroth|r com 6 acúmulos de |cffff9933Fogo Demoníaco|r concede a você |cFFFFFFFFRaiva Xorothiana|r, garantindo que seu próximo |cFFFFFFFFGolpe Infernal|r dentro de {{4}} golpeie criticamente."}
D[81547]={"^\nTeaches you |cFFFFFFFFDark Domination|r if you know Fel Domination%. \n\nUsing |cFFFFFFFFDark Domination|r resets your Hand of Gul'dan spells cooldown, additionally casting Hand of Gul'dan reduces the cooldown of Dark Domination by 10 seconds%.%s*$","\nEnsina |cFFFFFFFFDominação sombria|r se você conhece Dominação Vil.\n\nUsar |cFFFFFFFFDominação sombria|r reinicia a recarga de seus feitiços Mão de Gul'dan, além lançar Mão de Gul'dan reduz a recarga de Dominação Sombria em 10 segundos."}
D[81548]={"^Fel Domination/Dark Domination cooldown reduced by 4 seconds%.%s*$","Recarga de Dominação Vil/Dominação Sombria reduzidos em 4 segundos."}
