T[13]={"^Dominating undead%.%s*$","Domina mortos-vivos."}
T[142]={"^Dominating dragonkin%.%s*$","Domina um draconiano."}
T[205]={"^Damage dealt by |cffffffffFlames of Xoroth|r, when used with at least 3 |cffff9933Demonfire|r, now purges 1 magic effect and steals 1 magic effect from enemies%.%s*$","Quando usado com pelo menos 3 acúmulos de |cffff9933Chamas de Xoroth|r, o dano de |cffffffffFogo Demoníaco|r dissipa 1 efeito mágico e rouba 1 efeito mágico dos inimigos."}
T[272]={"^Block value increased by (.-)%%%.%s*$","Aumenta o valor de bloqueio em {{1}}%."}
T[462]={"^The next time you take damage you unleash a blast of hellfire upon enemies within (.-) yds, dealing Fire damage%.%s*$","Na próxima vez que receber dano, você libera uma explosão de fogo infernal contra os inimigos em um raio de {{1}} m, causando dano de Fogo."}
T[529]={"^Seared by infernal flames%.%s*$","Carbonizado por chamas infernais."}
T[558]={"^Allows Flames of Xoroth to benefit from your Attack Power%.%s*$","Permite que as Chamas de Xoroth se beneficiem de seu poder de ataque."}
T[559]={"^Reduces the cooldown of |cffffffffFlesh Hook|r by (.-)%% and allows it to pull up to (.-) enemies%.%s*$","Reduz a recarga de |cffffffffGancho de Carne|r em {{1}}% e permite que possa arrastar até {{2}} inimigos."}
T[586]={"^Causes every third |cffffffffInfernal Strike|r to call down a Molten Hellrain%.%s*$","Faz com que cada terceiro |cffffffffGolpe Infernal|r invoque uma Chuva Infernal de Magma."}
T[731]={"^Damage dealt by |cffffffffMeatsaw|r now increases the damage dealt by |cffffffffWarbringer|r and |cffffffffBrimstone Bludgeon|r on affected enemies by (.-)%% for (.-), stacking (.-) times%.%s*$","O dano causado por |cffffffffSerra de Carne|r agora aumenta o dano causado por |cffffffffArauto da Guerra|r e |cffffffffClava de Enxofre|r nos inimigos afetados em {{1}}% durante {{2}}, acumulando-se {{3}} vezes."}
T[733]={"^Allows Demon's Blood to stack (.-) additional times%.%s*$","Permite que a Sangue do Demônio se acumule {{1}} vezes mais."}
T[734]={"^|cffffffffWarbringer|r now increases the damage of your next 2 |cffffffffSevers|r or |cffffffffConsuming Blades|r by (.-)%% for (.-)%.\n\nAt the end of the duration, or when all stacks are consumed, you cast |cffffffffMeatsaw|r instantly%.%s*$","|cffffffffArauto da Guerra|r agora aumenta o dano de seu próximo 2 |cffffffffCortar|r ou |cffffffffLâminas Consumidoras|r em {{1}}% durante {{2}}.\n\nAo final do tempo, ou quando se consumam todos acúmulos, lança |cffffffffSerra de Carne|r de forma instantânea."}
T[737]={"^Increases the damage of |cfffffffffInfernal Strike|r and |cffffffffFlames of Xoroth|r by (.-)%%%.%s*$","Aumenta o dano de |cffffffffGolpe Infernal|r e |cffffffffChamas de Xoroth|r em {{1}}%."}
T[738]={"^Reduces the cooldown of |cffffffffFlesh Hook|r and |cffffffffHellhaul|r by (.-) sec%.%s*$","Reduzir a recarga de |cffffffffGancho de Carne|r e |cffffffffArrasto Infernal|r em {{1}} s."}
T[742]={"^Using a |cffffffffPestilence|r now removes 1 curse and disease effect and reduces all damage taken by (.-)%% for (.-)%.%s*$","Usando uma |cffffffffPestilência|r agora remove 1 efeito de maldição e doença e reduz todo dano recebido em {{1}}% durante {{2}}."}
T[746]={"^Increases the damage of |cffffffffGore|r by (.-)%%%.%s*$","Aumenta o dano de |cffffffffCornada|r em {{1}}%."}
T[747]={"^Reduces the Rage cost of |cffffffffSkulltaker|r by (.-) and increases its damage by (.-)%%%.%.%s*$","Reduzir o custo de Fúria de |cffffffffCarniceiro do Crânio|r em {{1}} e aumentar seu dano em {{2}}%."}
T[748]={"^Increases critical strike chance by (.-)%% and reduces the cooldown of |cffffffffGore|r by (.-) sec%.%s*$","Aumentar a chance de acerto crítico em {{1}}% e reduzir a recarga de |cffffffffCornada|r em {{2}} s."}
T[749]={"^Reduces the cooldown of |cffffffffBrimstone Bludgeon|r by (.-) sec%.%s*$","Reduzir a recarga de |cffffffffClava de Enxofre|r em {{1}} s."}
T[750]={"^Your physical critical strikes deal (.-)%% more damage and |cFFFFFFFFGore|r increases your movement speed by (.-)%% for (.-)%.%s*$","Seus acertos críticos Físicos causam {{1}}% a mais de dano, e |cFFFFFFFFCornada|r aumenta sua velocidade de movimento em {{2}}% durante {{3}}."}
T[751]={"^Increases the damage of Torn Flesh by (.-)%%%.%s*$","Aumenta o dano de Tornar carne em {{1}}%."}
T[1269]={"^Dealing damage will grant you 1 stack of Champion of the Legion%.%s*$","Causar dano concede a você 1 acúmulo de Campeão da Legião."}
T[1296]={"^Melee Physical damage dealt generates a stack of |cffffffffDemon's Blood|r%.%s*$","O dano Físico corpo a corpo causado gera um acúmulo de |cffffffffSangue de Demônio|r."}
T[1297]={"^Absorbing up to (.-) damage%. Melee attackers will suffer (.-) Fire damage when attacking you%.%s*$","Absorve até {{1}} de dano. Os atacantes corpo a corpo sofrerão {{2}} dano de Fogo ao atacar você."}
T[1500]={"^Stunned and is being dragged, dealing (.-) Physical damage every (.-) sec%.%s*$","Atordoado e está sendo arrastado, causando {{1}} de dano Físico a cada {{2}} s."}
T[1522]={"^Each time a |cffffffffHellfire Imp|r dies, reduce the cooldown of |cffffffffDemonic Grit|r by (.-) sec%.%s*$","Sempre que morre um |cffffffffDiabrete do Fogo Infernal|r, reduz a recarga de |cffffffffDeterminação Demoníaca|r em {{1}} s."}
T[1538]={"^Bound to the will of a Knight of Xoroth, transferring (.-)%% of all damage you take to them%.%s*$","Vinculado à vontade de um Cavaleiro de Xoroth, transfirien de {{1}}% de todo dano que recebe a eles."}
T[1539]={"^Taking (.-) Shadow damage every (.-) sec%.%s*$","Recebe {{1}} dano de Sombra a cada {{2}} s."}
T[1540]={"^Fire Damage taken and your chance to be critically struck by Fire Damage increased by (.-)%%%.%s*$","O dano recebido por Fogo e sua chance de ser atingido criticamente por Fogo aumentam em {{1}}%."}
T[1557]={"^Threat generation increased by (.-)%%%. Block rating increased by (.-)%% of Strength%. Damage dealt reduced by (.-)%%%.\n\nWhenever you take damage you will generate (.-) Rage%.%s*$","A geração de ameaça aumenta em {{1}}%. O Índice de Bloqueio aumenta em {{2}}% da Força e o dano causado é reduzido em {{3}}%.\n\nSempre que você recebe dano, gera {{4}} de Raiva."}
T[1570]={"^Block chance increased by (.-)%%, block value increased by (.-)%%%. Blocking an attack triggers Hellish Rebuke%.%s*$","A chance de bloqueio aumenta em {{1}}% e o valor de bloqueio em {{2}}%. Bloquear um ataque ativa Repreensão Infernal."}
T[1571]={"^Block chance increased by (.-)%%, block value increased by (.-)%%%.%s*$","A chance de bloqueio aumenta em {{1}}%, o valor do bloqueio aumenta em {{2}}%."}
T[1767]={"^The Knight of Xoroth's next Demonflare deals (.-)%% increased initial damage to you%.%s*$","O próximo Clarão Demoníaco do Cavaleiro de Xoroth causa a você dano inicial aumenta em {{1}}%."}
